J=['HASSAN','HAMAN','HAMMED']
# dedup
seen=set(); uniq=[]
for row in data:
    key=(row[1],row[2])
    if key in seen: continue
    seen.add(key); uniq.append(row)
print('uniq',len(uniq))
for r in uniq: print(r)
# sort
jpos={n:i for i,n in enumerate(J)}
def sortkey(row):
    name=row[1]
    if name in jpos:
        return (0, jpos[name])
    return (1, 0)  # non-J keep original order -> stable
out=sorted(uniq, key=sortkey)
print('OUT')
for r in out: print(r)
